function rawInput() {
  const item = $input.first().json || {};
  let body = item.body;
  if (typeof body === 'string') {
    try { body = JSON.parse(body || '{}'); } catch (e) { body = {}; }
  }
  body = body || {};
  const query = item.query || {};
  return Object.assign({}, item, query, body);
}

function cleanString(v) {
  if (v === undefined || v === null) return '';
  const s = String(v).trim();
  if (s.toLowerCase() === 'null' || s.toLowerCase() === 'undefined' || s === '[null]') return '';
  return s;
}

function normalizeShippingMethod(val) {
  const s = cleanString(val).toLowerCase();
  if (s.includes('air') || s.includes('plane') || s.includes('flight')) return 'air';
  if (s.includes('road') || s.includes('truck') || s.includes('land') || s.includes('ground')) return 'road';
  if (s.includes('multi') || s.includes('combined')) return 'multimodal';
  if (s.includes('ocean') || s.includes('sea') || s.includes('ship') || s.includes('vessel') || s.includes('maritime')) return 'ocean';
  return 'ocean';
}

function asBool(v) {
  if (v === true || v === false) return v;
  const s = String(v == null ? '' : v).trim().toLowerCase();
  return s === 'true' || s === '1' || s === 'yes';
}

const p = rawInput();

const fullName = cleanString(p.full_name || p.name || p.customer_name || p.contact_name);
const email = cleanString(p.work_email || p.email || p.customer_email).toLowerCase();
const phone = cleanString(p.phone_number || p.phone || p.mobile);
const company = cleanString(p.company_name || p.company || p.business_name) || null;
const origin = cleanString(p.origin || p.origin_city || p.from || p.pickup_location);
const destination = cleanString(p.destination || p.destination_city || p.to || p.delivery_location);
const shippingMethod = normalizeShippingMethod(p.shipping_method || p.shipping_mode || p.method || p.freight_type);
const weight = cleanString(p.estimated_weight || p.weight || p.weight_kg) || null;
const departureDate = cleanString(p.preferred_departure_date || p.departure_date || p.date || p.shipping_date) || null;
const details = cleanString(p.additional_details || p.details || p.notes || p.cargo_description) || null;

const isTextOnly = asBool(p.is_text_only);
const channel = isTextOnly ? 'chat_agent' : 'voice_agent';

const missing = [];
if (!fullName) missing.push('full_name');
if (!email && !phone) missing.push('work_email or phone_number');
if (!origin) missing.push('origin');
if (!destination) missing.push('destination');

if (missing.length > 0) {
  const speech = "To prepare your freight quote, I need your name, " + (!email && !phone ? "an email or phone number, " : "") + "origin location, and destination. Could you please share those details?";
  return [{
    json: {
      valid: false,
      http_status: 422,
      error_body: {
        ok: false,
        status: 'validation_error',
        message: speech,
        missing: missing
      }
    }
  }];
}

const quotePayload = {
  full_name: fullName,
  company_name: company,
  work_email: email || (phone ? phone.replace(/\D/g, '') + '@placeholder.quote' : 'guest@logistics.quote'),
  phone_number: phone || null,
  origin: origin,
  destination: destination,
  shipping_method: shippingMethod,
  estimated_weight: weight,
  preferred_departure_date: departureDate ? departureDate.slice(0, 10) : null,
  additional_details: details,
  consent_to_contact: true,
  source: channel,
  status: 'new'
};

return [{
  json: {
    valid: true,
    http_status: 200,
    payload: quotePayload
  }
}];

const res = $input.first().json;

if (res.error || (res.statusCode && res.statusCode >= 400) || (res.body && res.body.error)) {
  const errMsg = (res.body && (res.body.message || res.body.error)) || res.message || res.error || 'Database error';
  return [{
    json: {
      ok: false,
      status: 'error',
      message: "I encountered an error submitting your quote request: " + errMsg + ". Please try again or speak with an agent.",
      http_status: 500
    }
  }];
}

let quote = null;
if (Array.isArray(res)) {
  quote = res.length > 0 ? res[0] : null;
} else if (res && res.body) {
  if (Array.isArray(res.body)) {
    quote = res.body.length > 0 ? res.body[0] : null;
  } else if (typeof res.body === 'object' && res.body.quote_id) {
    quote = res.body;
  }
} else if (res && res.quote_id) {
  quote = res;
}

const quoteId = quote && quote.quote_id ? quote.quote_id : 'QT-CONFIRMED';
const name = quote && quote.full_name ? quote.full_name : 'Customer';
const origin = quote && quote.origin ? quote.origin : 'origin';
const destination = quote && quote.destination ? quote.destination : 'destination';
const method = quote && quote.shipping_method ? quote.shipping_method : 'freight';
const email = quote && quote.work_email ? quote.work_email : '';

const speech = "Thank you, " + name + "! Your quote request has been submitted successfully with Quote ID " + quoteId + ". We have logged your " + method + " shipment from " + origin + " to " + destination + ". Our logistics team will review current rates and send your full quotation to " + email + " shortly.";

return [{
  json: {
    ok: true,
    status: 'quote_created',
    message: speech,
    quote_id: quoteId,
    full_name: name,
    origin: origin,
    destination: destination,
    shipping_method: method,
    work_email: email,
    created_at: quote && quote.created_at ? quote.created_at : new Date().toISOString()
  }
}];

