  body = body || {};
  const query = item.query || {};
  return Object.assign({}, item, query, body);
}

function cleanString(v) {
  if (v === undefined || v === null) return '';
  const s = String(v).trim();
  if (s.toLowerCase() === 'null' || s.toLowerCase() === 'undefined' || s === '[null]') return '';
  return s;
}

function normalizeShippingMethod(val) {
  const s = cleanString(val).toLowerCase();
  if (s.includes('air') || s.includes('plane') || s.includes('flight')) return 'air';
  if (s.includes('road') || s.includes('truck') || s.includes('land') || s.includes('ground')) return 'road';
