const order = $('Normalize & Structure Order Data').first().json || {};
let html = '';

try {
  const aiOutput = $input.first().json || {};
  html = aiOutput.text || (aiOutput.message && aiOutput.message.content) || aiOutput.content || '';
  html = html.replace(/^```html\s*/i, '').replace(/```$/i, '').trim();
} catch (e) {
  html = '';
}

// If AI did not return valid HTML (e.g. credentials not set yet), use high-end built-in HTML summary template
if (!html || !html.includes('<html')) {
  html = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>Order Confirmation - ${order.order_id || 'Summary'}</title>
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; color: #0f172a; margin: 0; padding: 32px; background: #ffffff; }
    .header { border-bottom: 2px solid #2563eb; padding-bottom: 16px; margin-bottom: 24px; display: flex; justify-content: space-between; align-items: flex-end; }
    .brand { font-size: 24px; font-weight: 800; color: #0f172a; letter-spacing: 0.5px; }
    .brand span { color: #2563eb; }
    .title { font-size: 13px; text-transform: uppercase; letter-spacing: 1.5px; color: #64748b; font-weight: 600; margin-top: 4px; }
    .order-tag { background: #eff6ff; border: 1px solid #bfdbfe; color: #1d4ed8; font-family: monospace; font-size: 14px; font-weight: 700; padding: 6px 14px; border-radius: 6px; }
    .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-bottom: 24px; }
    .card { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; padding: 18px; }
    .card-title { font-size: 12px; font-weight: 700; text-transform: uppercase; color: #475569; letter-spacing: 1px; margin-bottom: 12px; border-bottom: 1px solid #e2e8f0; padding-bottom: 6px; }
    .row { display: flex; justify-content: space-between; margin-bottom: 8px; font-size: 13px; }
    .row .label { color: #64748b; }
    .row .val { font-weight: 600; color: #0f172a; text-align: right; }
    .status-badge { display: inline-block; background: #dcfce7; color: #15803d; font-size: 12px; font-weight: 700; padding: 3px 10px; border-radius: 12px; }
    .footer { margin-top: 36px; padding-top: 16px; border-top: 1px solid #e2e8f0; font-size: 12px; color: #64748b; text-align: center; line-height: 1.6; }
    .footer a { color: #2563eb; text-decoration: none; font-weight: 600; }
  </style>
</head>
<body>
  <div class="header">
    <div>
      <div class="brand">CIKETO <span>LOGISTICS</span></div>
      <div class="title">Freight Booking Confirmation & Order Detail Summary</div>
    </div>
    <div class="order-tag">${order.order_id || 'CKT-CONFIRMED'}</div>
  </div>

  <div class="grid">
    <div class="card">
      <div class="card-title">Customer & Shipper</div>
      <div class="row"><span class="label">Customer:</span><span class="val">${order.customer_name || 'Valued Customer'}</span></div>
      <div class="row"><span class="label">Company:</span><span class="val">${order.company_name || 'N/A'}</span></div>
      <div class="row"><span class="label">Email:</span><span class="val">${order.email || 'N/A'}</span></div>
      <div class="row"><span class="label">Phone:</span><span class="val">${order.phone || 'N/A'}</span></div>
      <div class="row"><span class="label">Booking Date:</span><span class="val">${(order.created_at || '').slice(0, 10)}</span></div>
    </div>

    <div class="card">
      <div class="card-title">Routing & Transit</div>
      <div class="row"><span class="label">Origin:</span><span class="val">${order.origin || 'N/A'}</span></div>
      <div class="row"><span class="label">Destination:</span><span class="val">${order.destination || 'N/A'}</span></div>
      <div class="row"><span class="label">Transport Method:</span><span class="val">${(order.shipping_method || 'FREIGHT').toUpperCase()}</span></div>
      <div class="row"><span class="label">Departure Date:</span><span class="val">${order.preferred_departure_date || 'TBD'}</span></div>
      <div class="row"><span class="label">Est. Delivery:</span><span class="val">${order.estimated_delivery_date || 'TBD'}</span></div>
    </div>
  </div>

  <div class="grid">
    <div class="card">
      <div class="card-title">Cargo Specifications</div>
      <div class="row"><span class="label">Description:</span><span class="val">${order.cargo_description || 'General Cargo'}</span></div>
      <div class="row"><span class="label">Weight:</span><span class="val">${order.weight_kg ? order.weight_kg + ' kg' : 'N/A'}</span></div>
      <div class="row"><span class="label">Packages / Pieces:</span><span class="val">${order.packages || 'N/A'}</span></div>
      <div class="row"><span class="label">Special Notes:</span><span class="val">${order.notes || 'None'}</span></div>
    </div>

    <div class="card">
      <div class="card-title">Commercial & Status</div>
      <div class="row"><span class="label">Total Amount:</span><span class="val">${order.amount ? '$' + Number(order.amount).toFixed(2) + ' ' + (order.currency || 'USD') : 'Rate on Confirmation'}</span></div>
      <div class="row"><span class="label">Order Status:</span><span class="val"><span class="status-badge">Order Placed</span></span></div>
      <div class="row"><span class="label">Payment Terms:</span><span class="val">Standard Commercial Invoice</span></div>
    </div>
  </div>

  <div class="footer">
    <p>Track live shipment status anytime at <strong><a href="https://ciketo.com/track-order">ciketo.com/track-order</a></strong> with Order ID <strong>${order.order_id || ''}</strong>.</p>
    <p>Ciketo Global Freight Logistics • 24/7 Operations Support: support@ciketo.com</p>
  </div>
</body>
</html>`;
}

return [{
  json: {
    source: html,
    filename: 'Order-Confirmation-' + (order.order_id || 'Summary') + '.pdf',
    customer_email: order.email || '',
    customer_name: order.customer_name || 'Customer',
    order_id: order.order_id || '',
    origin: order.origin || '',
    destination: order.destination || '',
    shipping_method: order.shipping_method || 'ocean'
  }
}];

