  const s = String(v).trim();
  if (s.toLowerCase() === 'null' || s.toLowerCase() === 'undefined' || s === '[null]') return '';
  return s;
}

function normalizeOrderId(val) {
  let s = cleanString(val).toUpperCase().replace(/\s+/g, '-');
  if (/^\d{6}$/.test(s)) {
    const year = new Date().getFullYear();
