  if (!customerName) {
    errorMsg = "Please provide your name so I can create a support ticket for you.";
  } else if (!email && !phone) {
    errorMsg = "Please provide a contact phone number or email address so our team can follow up with you.";
  } else if (!summary || summary.length < 3) {
    errorMsg = "Please provide a brief summary of what you need assistance with.";
  } else {
    errorMsg = "Please provide a few more details about your inquiry.";
  }
}

const summaryHash = simpleHash((summary || '').toLowerCase());
const dedupeKey = `${rawConvId}:${category}:${summaryHash}`;

return [{
  json: {
    valid: isValid,
    customer_name: customerName,
    email: email,
    phone: phone,
    order_id: orderId,
    category: category,
    priority: priority,
    summary: summary,
    details: details,
    source: 'chat_agent',
    is_handoff: true,
    conversation_id: rawConvId,
    dedupe_key: dedupeKey,
    http_status: isValid ? 200 : 422,
    error_body: isValid ? null : {
      ok: false,
      status: 'validation_error',
      message: errorMsg,
      missing: missing
    }
  }
}];

const res = $input.first().json;
let ticket = {};
try {
  ticket = $('Map Ticket').first().json || {};
} catch (e) {
  ticket = {};
}

let orders = [];
if (Array.isArray(res)) {
  orders = res;
} else if (res && res.body) {
  orders = Array.isArray(res.body) ? res.body : (res.body.id || res.body.order_id ? [res.body] : []);
} else if (res && (res.id || res.order_id)) {
  orders = [res];
}

let orderUuid = null;
let identityVerified = false;

if (orders.length === 1 && orders[0] && (orders[0].id || orders[0].order_id)) {
  const matchedOrder = orders[0];
  orderUuid = matchedOrder.id || null;

  const ticketEmail = (ticket.email || '').toLowerCase().trim();
  const orderEmail = (matchedOrder.email || '').toLowerCase().trim();
  const emailMatches = Boolean(ticketEmail && orderEmail && ticketEmail === orderEmail);

  const ticketDigits = (ticket.phone || '').replace(/\D/g, '');
  const orderDigits = (matchedOrder.phone || '').replace(/\D/g, '');
  const phoneMatches = Boolean(
    ticketDigits.length >= 7 &&
    orderDigits.length >= 7 &&
    ticketDigits.slice(-7) === orderDigits.slice(-7)
  );

  identityVerified = emailMatches || phoneMatches;
}

const payload = {
  customer_name: ticket.customer_name || '',
  email: ticket.email || null,
  phone: ticket.phone || null,
  order_id: ticket.order_id || null,
  order_uuid: orderUuid,
  category: ticket.category || 'other',
  priority: ticket.priority || 'normal',
  summary: ticket.summary || '',
  details: ticket.details || '',
  source: 'chat_agent',
  is_handoff: true,
  identity_verified: identityVerified,
  conversation_id: ticket.conversation_id || '',
  dedupe_key: ticket.dedupe_key || ''
};

return [{
  json: {
    ticket_payload: payload,
    conversation_id: ticket.conversation_id,
    customer_name: ticket.customer_name
  }
}];

let ticket = {};
try {
  ticket = $('Map Ticket').first().json || $input.first().json || {};
} catch (e) {
  ticket = $input.first().json || {};
}

const payload = {
  customer_name: ticket.customer_name || '',
  email: ticket.email || null,
  phone: ticket.phone || null,
  order_id: null,
  order_uuid: null,
  category: ticket.category || 'other',
  priority: ticket.priority || 'normal',
  summary: ticket.summary || '',
  details: ticket.details || '',
  source: 'chat_agent',
  is_handoff: true,
  identity_verified: false,
  conversation_id: ticket.conversation_id || '',
  dedupe_key: ticket.dedupe_key || ''
};

return [{
  json: {
    ticket_payload: payload,
    conversation_id: ticket.conversation_id,
    customer_name: ticket.customer_name
  }
}];

const res = $input.first().json;

let ticketData = null;
if (res && res.id) {
  ticketData = res;
} else if (res && res.body) {
  ticketData = res.body;
} else if (Array.isArray(res) && res.length > 0) {
  ticketData = res[0];
}

let mapData = {};
try {
  mapData = $('Map Ticket').first().json || {};
} catch (e) {
  mapData = {};
}

const ticketId = (ticketData && ticketData.ticket_id) || 'TKT-' + new Date().getFullYear() + '-CREATED';
const ticketUuid = (ticketData && ticketData.id) || null;
const isDuplicate = Boolean(ticketData && ticketData.duplicate);
const customerName = mapData.customer_name || 'Customer';
const convId = mapData.conversation_id || '';

let speech = '';
if (isDuplicate) {
  speech = "Support ticket " + ticketId + " has already been logged for this conversation. A support agent is currently reviewing it.";
} else {
  speech = "I have opened support ticket " + ticketId + " for " + customerName + ". Our operations team has been notified and a specialist will follow up shortly.";
}

return [{
  json: {
    ok: true,
    status: 'ticket_created',
    ticket_id: ticketId,
    ticket_uuid: ticketUuid,
    duplicate: isDuplicate,
    customer_name: customerName,
    conversation_id: convId,
    message: speech,
    response_body: {
      ok: true,
      status: 'ticket_created',
      ticket_id: ticketId,
      ticket_uuid: ticketUuid,
      duplicate: isDuplicate,
      message: speech
    }
  }
}];

const convRes = $input.first().json;
let ticketInfo = {};
try {
  ticketInfo = $('Format Ticket Response').first().json || {};
} catch (e) {
  ticketInfo = {};
}

const ticketUuid = ticketInfo.ticket_uuid;
if (!ticketUuid) {
  return [];
}

const hasError = Boolean(
  convRes.error ||
  (convRes.statusCode && convRes.statusCode >= 400) ||
  (convRes.status && convRes.status >= 400)
);

let rawTranscript = null;
if (!hasError && Array.isArray(convRes.transcript)) {
  rawTranscript = convRes.transcript;
} else if (!hasError && convRes.body && Array.isArray(convRes.body.transcript)) {
  rawTranscript = convRes.body.transcript;
}

let noteKind = 'transcript';
let transcriptText = '';

if (hasError || rawTranscript === null || rawTranscript.length === 0) {
  noteKind = 'system';
  transcriptText = 'Transcript could not be retrieved.';
} else {
  const lines = [];
  for (const entry of rawTranscript) {
    if (!entry || entry.message === null || entry.message === undefined) continue;
    const msg = String(entry.message).trim();
    if (!msg) continue;
    const role = String(entry.role || '').toLowerCase();
    if (role === 'user') {
      lines.push('Customer: ' + msg);
    } else if (role === 'agent') {
      lines.push('Agent: ' + msg);
    } else {
      lines.push('System: ' + msg);
    }
  }

  if (lines.length === 0) {
    noteKind = 'system';
    transcriptText = 'Transcript could not be retrieved.';
  } else {
    transcriptText = lines.join('\n');
    const maxChars = 20000;
    if (transcriptText.length > maxChars) {
      const marker = '\n[truncated]';
      transcriptText = transcriptText.slice(0, maxChars - marker.length) + marker;
    }
  }
}

return [{
  json: {
    p_ticket_uuid: ticketUuid,
    p_author: 'system',
    p_kind: noteKind,
    p_body: transcriptText
  }
}];
